def get_premium_year_decote(year):

    current_year = 2026
    age = current_year - int(year)

    return -(age * 5000)


def get_premium_km_decote(km):

    km = int(km)

    if km <= 20000:
        return 0
    elif km <= 40000:
        return -2000
    elif km <= 60000:
        return -4000
    elif km <= 80000:
        return -7000
    elif km <= 100000:
        return -10000
    elif km <= 120000:
        return -14000
    elif km <= 150000:
        return -18000

    return -25000

MOTORISATION_BONUS = {
    "<1.2": -1500,
    "1.2-1.4": -750,
    "1.5-1.6": 0,
    "1.7-2.0": 1000,
    "2.1-3.0": 2500,
    ">3.0": 5000
}
def get_motorisation_bonus(motorisation):

    m = str(motorisation).lower()

    if "1.0" in m or "1.1" in m:
        return MOTORISATION_BONUS["<1.2"]

    elif "1.2" in m or "1.3" in m or "1.4" in m:
        return MOTORISATION_BONUS["1.2-1.4"]

    elif "1.5" in m or "1.6" in m:
        return MOTORISATION_BONUS["1.5-1.6"]

    elif "1.7" in m or "1.8" in m or "1.9" in m or "2.0" in m:
        return MOTORISATION_BONUS["1.7-2.0"]

    elif "2.1" in m or "2.2" in m or "2.3" in m or "2.5" in m or "3.0" in m:
        return MOTORISATION_BONUS["2.1-3.0"]

    return MOTORISATION_BONUS[">3.0"]

NORMALIZED_DATASET = {}

for brand, models in FULL_DATASET.items():

    normalized_brand = normalize_text(brand)

    NORMALIZED_DATASET[normalized_brand] = {}

    for model, years in models.items():

        normalized_model = normalize_text(model)

        NORMALIZED_DATASET[normalized_brand][normalized_model] = years


def load_users():
    url = f"https://docs.google.com/spreadsheets/d/{SHEET_ID}/export?format=csv"
    df = pd.read_csv(url)

    df["username"] = df["username"].astype(str).str.strip()
    df["password"] = df["password"].astype(str).str.strip()
    df["expire"] = pd.to_datetime(df["expire"], errors="coerce")

    return df

def check_login(username):

    df = load_users()

    user = df[
        df["username"].astype(str).str.strip()
        == str(username).strip()
    ]

    if user.empty:
        return "error"

    expire_date = pd.to_datetime(
        user.iloc[0]["expire"],
        errors="coerce"
    )

    if pd.isna(expire_date):
        return "expired"

    if expire_date < pd.Timestamp.now():

        if str(user.iloc[0]["trial"]).strip().upper() == "TRUE":
            return "trial_expired"

        return "subscription_expired"

    return "ok"
def send_to_webhook(username, societe, siret):
    

    data = {
    "username": username,
    "trial": True,
    "price": 0
}

    try:
        requests.post(WEBHOOK_URL, json=data, timeout=10)
    except:
        pass

def clean_prices(prices):
    if len(prices) < 5:
        return prices

    prices = sorted(prices)
    median = statistics.median(prices)

    filtered = [
        p for p in prices
        if (median * 0.6) <= p <= (median * 1.4)
    ]

    if len(filtered) < 3:
        return prices

    return filtered

