if calcul:
    if normalize_text(marque) in PREMIUM_BRANDS:

        st.error("Moteur premium en cours d'intégration")
    
        st.stop()
    kms_disponibles = [30000, 60000, 90000, 120000, 150000]

    km_reference = min(kms_disponibles, key=lambda x: abs(x - km))

    prix_marche = NORMALIZED_DATASET[
        normalize_text(marque)
    ][
        normalize_text(modele)
    ][
        normalize_text(finition)
    ][
        annee
    ][
        km_reference
    ]
    
    finition_bonus = (
        PREMIUM_FINITIONS
        .get(normalize_text(marque), {})
        .get(normalize_text(finition), 0)
    )

    prix_marche += finition_bonus    
    
    # 🔥 MODE STABLE (désactivation learning / scraping)
   
    # 🔥 LOGIQUE PRO FOURCHETTE
    


    # ✅ historique (après calcul)
    st.session_state.historique.insert(0, {
    
        "date": datetime.now().strftime("%d/%m/%Y %H:%M"),
        "marque": marque,
        "modele": modele,
        "finition": finition,
        "motorisation": motorisation,
        "carburant": carburant,
        "boite": boite,
        "transmission": transmission,
        "options": options,
        "departement": departement,
        "annee": annee,
        "km": km,
        "prix_marche": prix_marche

})

    st.session_state.historique = st.session_state.historique[:20]

    # ================================
    # CALCUL DATASET
    # ================================

    kms_disponibles = sorted([30000, 60000, 90000, 120000, 150000])

    if km <= kms_disponibles[0]:

        prix_marche = NORMALIZED_DATASET[
            normalize_text(marque)
        ][
            normalize_text(modele)
        ][
            normalize_text(finition)
        ][
            annee
        ][
            30000
        ]

    elif km >= kms_disponibles[-1]:

       prix_marche = NORMALIZED_DATASET[
            normalize_text(marque)
        ][
            normalize_text(modele)
        ][
            normalize_text(finition)
        ][
            annee
        ][
            150000
        ]

    else:

        for i in range(len(kms_disponibles) - 1):

            km_bas = kms_disponibles[i]
            km_haut = kms_disponibles[i + 1]

            if km_bas <= km <= km_haut:

               prix_bas = NORMALIZED_DATASET[
                   normalize_text(marque)
               ][
                   normalize_text(modele)
               ][
                    normalize_text(finition)
               ][  
                   annee
               ][
                   km_bas
               ]

               prix_haut = NORMALIZED_DATASET[
                    normalize_text(marque)
               ][
                    normalize_text(modele)
               ][
                    normalize_text(finition)
               ][
                    annee
               ][
                    km_haut
               ]

               ratio = (km - km_bas) / (km_haut - km_bas)

               prix_marche = round(
               prix_bas - ((prix_bas - prix_haut) * ratio)
                   
               )

               break

    prix_estime = round(prix_marche / 10) * 10

    bas_affiche = prix_estime 
    haut_affiche = prix_estime + 1500


    # 🔥 STOCKAGE RESULTAT (pour éviter reset)
    st.session_state.resultat = {
    
    
        "prix_marche": prix_marche,
        "prix_estime": prix_estime,
        "bas_affiche": bas_affiche,
        "haut_affiche": haut_affiche
    }

