    buffer.write(f"Kilométrage : {km} km\n")
    buffer.write(f"Carburant : {carburant}\n")
    buffer.write(f"Boîte : {boite}\n")

    buffer.write("\n===== PRIX =====\n")

    buffer.write(f"Prix marché estimé : {prix_estime} €\n")

    buffer.write(
        f"Fourchette estimée : {bas_affiche} € à {haut_affiche} €\n"
    )

